INSERT INTO fut_evolution_log VALUES(3,30,2492,'Intro to Repeatable Evolutions',1,'2026-09-19','2026-09-19',65,66,'{"PAC": 77, "SHO": 79, "PAS": 56, "DRI": 69, "DEF": 22, "PHY": 77}',NULL,NULL,NULL,NULL,NULL,'scripts/fut_club.py evolve (2026-09-19 기록) · 적용 후 값 출처: 카탈로그 levels[0] 총상승(Overall +1). ⚠️ fut.gg path_json은 기본 카드(65) 기준이라 쓰지 않았다','MEASURED(사용자 행위) — 적용·완료는 사용자 보고. OVR은 카탈로그 상승폭 +1을 현재값 75에 더한 값이고, 6대 스탯 변화는 EA가 공개하지 않아 미기록(결손이지 0이 아니다)','반복 가능 진화 소개(Intro to Repeatable Evolutions) 1차 — 사용자 보고 2026-09-19. 시야+3·짧은패스+3·중거리슛+4·반응력+4 · 2026-09-19 정정: Glow Up 무효 확인으로 기준이 기본 카드 65였다',0);
